import {rehabRegions,rehabSides,rehabStatuses,rehabContentTypes,rehabLanguages} from './rehab-schema.js';
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const field=(t,h,name,label,value='',type='text',extra='')=>`<label>${h(t(label))}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
const area=(t,h,name,label,value='',max=1000,required=false)=>`<label>${h(t(label))}<textarea name="${name}" maxlength="${max}" ${required?'required':''}>${h(value)}</textarea></label>`;
const select=(t,h,name,label,options,value='')=>`<label>${h(t(label))}<select name="${name}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select></label>`;
const hidden=(h,name,value)=>`<input type="hidden" name="${name}" value="${h(value)}">`;
const form=(t,h,operation,body,id='',label='save')=>`<form class="stack" data-form="programs">${hidden(h,'module','rehab')}${hidden(h,'operation',operation)}${id?hidden(h,'id',id):''}${body}<button class="primary" type="submit">${h(t(label))}</button></form>`;
const action=(t,h,btn,op,id,label,attrs='')=>btn(t(label),'programAction',`data-module="rehab" data-op="${op}" data-id="${h(id)}" ${attrs}`,'secondary');
const details=(key,title,body,{open=false,edit=false}={})=>`<details class="card rehab-disclosure${edit?' rehab-edit':''}" data-disclosure-key="rehab:${key}" ${open?'open':''}><summary><strong>${title}</strong></summary><div class="stack rehab-body">${body}</div></details>`;
const empty=(t,h,key='noItems')=>`<p class="empty">${h(t(key))}</p>`;
const regionOptions=t=>rehabRegions.map(x=>[x,t('rehabRegion_'+x)]);
const sideOptions=t=>rehabSides.map(x=>[x,t('rehabSide_'+x)]);
const statusOptions=t=>rehabStatuses.map(x=>[x,t('rehabStatus_'+x)]);
const contentOptions=t=>rehabContentTypes.map(x=>[x,t('rehabType_'+x)]);
function caseFields(t,h,r){return field(t,h,'title','programTitle',r?.title,'text','required maxlength="100"')+field(t,h,'date','recordDate',r?.date||localDate(),'date','required')+select(t,h,'region','rehabRegion',regionOptions(t),r?.region||'unspecified')+select(t,h,'side','rehabSide',sideOptions(t),r?.side||'unspecified')+select(t,h,'status','rehabCaseStatus',statusOptions(t),r?.status||'open')+area(t,h,'note','programInjury',r?.note,1000,true)+area(t,h,'plan','rehabManualPlan',r?.plan,1000)+field(t,h,'progress','rehabSelfProgress',r?.progress??0,'number','required min="0" max="100" step="1"');}
function checkinFields(t,h,r){return field(t,h,'date','recordDate',r?.date||localDate(),'date','required')+field(t,h,'progress','rehabSelfProgress',r?.progress??0,'number','required min="0" max="100" step="1"')+field(t,h,'discomfort','rehabDiscomfort',r?.discomfort??'','number','min="0" max="10" step="1"')+area(t,h,'note','rehabCheckinNote',r?.note,1000);}
function taskFields(t,h,r){return field(t,h,'taskTitle','rehabTaskTitle',r?.title,'text','required maxlength="120"')+area(t,h,'taskNote','rehabTaskNote',r?.note,500);}
function contentFields(t,h,r){return field(t,h,'title','programTitle',r?.title,'text','required maxlength="100"')+select(t,h,'region','rehabRegion',regionOptions(t),r?.region||'unspecified')+select(t,h,'contentType','rehabContentType',contentOptions(t),r?.type||'guide')+select(t,h,'language','language',rehabLanguages.map(x=>[x,t('lang_'+x)]),r?.language||'en')+area(t,h,'description','programDescription',r?.description,1000)+area(t,h,'content','rehabDraftBody',r?.content,12000);}

function privateCase(r,{t,h,btn,choices},shared=false){
  const checks=[...(r.checkins||[])].sort((a,b)=>b.date.localeCompare(a.date)),tasks=r.tasks||[],done=tasks.filter(x=>x.completed).length;
  const checkins=checks.map(x=>`<article class="rule stack"><div class="row space wrap"><time datetime="${h(x.date)}">${h(x.date)}</time><span class="badge">${x.progress}%</span></div>${x.discomfort!=null?`<small>${h(t('rehabDiscomfort'))}: ${x.discomfort}/10</small>`:''}${x.note?`<p>${h(x.note)}</p>`:''}${shared?'':`${details(`checkin-edit:${h(x.id)}`,h(t('wellnessEdit')),form(t,h,'rehabCheckinUpdate',hidden(h,'checkinId',x.id)+checkinFields(t,h,x),r.id),{edit:true})}${action(t,h,btn,'rehabCheckinDelete',r.id,'remove',`data-checkin="${h(x.id)}"`)}`}</article>`).join('')||empty(t,h);
  const taskList=tasks.map(x=>`<article class="rule stack"><div class="row space wrap"><b>${h(x.title)}</b><span class="badge ${x.completed?'green':''}">${h(t(x.completed?'done':'rehabPendingTask'))}</span></div>${x.note?`<p>${h(x.note)}</p>`:''}${shared?'':`<div class="row wrap">${action(t,h,btn,'rehabTaskToggle',r.id,x.completed?'healthUndo':'healthComplete',`data-task="${h(x.id)}" data-completed="${!x.completed}"`)}${action(t,h,btn,'rehabTaskDelete',r.id,'remove',`data-task="${h(x.id)}"`)}</div>${details(`task-edit:${h(x.id)}`,h(t('wellnessEdit')),form(t,h,'rehabTaskUpdate',hidden(h,'taskId',x.id)+taskFields(t,h,x),r.id),{edit:true})}`}</article>`).join('')||empty(t,h);
  const share=shared?'':details(`share:${h(r.id)}`,h(t('consent')),`<p class="notice">${h(t('rehabSharingNote'))}</p>${form(t,h,'share',select(t,h,'linkId','consent',[['none',t('programPrivate')],...choices.map(l=>[l.id,l.name])],r.shareLink||'none'),r.id)}`,{edit:true});
  const edit=shared?'':details(`case-edit:${h(r.id)}`,h(t('wellnessEdit')),form(t,h,'update',caseFields(t,h,r),r.id),{edit:true});
  const title=`${h(shared?r.memberName+' · '+r.title:r.title)} <span class="badge ${r.status==='open'?'green':''}">${h(t('rehabStatus_'+r.status))}</span>`;
  const body=`<div class="row wrap"><span class="badge">${h(t('rehabRegion_'+r.region))}</span><span class="badge">${h(t('rehabSide_'+r.side))}</span><small>${h(r.date)}</small></div><div class="stack"><b>${h(t('programInjury'))}</b><p>${h(r.note)}</p>${r.plan?`<b>${h(t('rehabManualPlan'))}</b><p>${h(r.plan)}</p>`:''}<small>${h(t('rehabSelfProgress'))}: ${r.progress}%</small><progress value="${r.progress}" max="100"></progress></div>${edit}${details(`tasks:${h(r.id)}`,`${h(t('rehabPlanChecklist'))} · ${done}/${tasks.length}`,`<p class="muted">${h(t('rehabManualPlanHint'))}</p>${shared?'':details(`task-add:${h(r.id)}`,h(t('rehabAddTask')),form(t,h,'rehabTaskCreate',taskFields(t,h),r.id),{edit:true})}${taskList}`)}${details(`timeline:${h(r.id)}`,`${h(t('rehabTimeline'))} · ${checks.length}`,`${shared?'':details(`checkin-add:${h(r.id)}`,h(t('rehabAddCheckin')),form(t,h,'rehabCheckinCreate',checkinFields(t,h),r.id),{edit:true})}${checkins}`)}${share}${shared?'':`<div class="row wrap">${action(t,h,btn,r.status==='open'?'rehabClose':'rehabReopen',r.id,r.status==='open'?'rehabCloseCase':'rehabReopenCase')}${action(t,h,btn,'delete',r.id,'remove')}</div>`}`;
  return details(`case:${shared?'shared:':''}${h(r.id)}`,title,body);
}

function libraryPage(content,{t,h,btn,filter={}}){
  if(!content)return '';
  const rows=content.items.filter(r=>(!filter.language||r.language===filter.language)&&(!filter.region||r.region===filter.region)&&(!filter.contentType||r.type===filter.contentType)&&(!filter.query||[r.title,r.description].some(v=>String(v).toLowerCase().includes(filter.query.toLowerCase()))));
  const filters=`<form class="row wrap" data-form="programFilter">${hidden(h,'module','rehab')}${field(t,h,'query','programSearch',filter.query||'','search')}${select(t,h,'language','language',[['',t('all')],...rehabLanguages.map(x=>[x,t('lang_'+x)])],filter.language||'')}${select(t,h,'region','rehabRegion',[['',t('all')],...regionOptions(t)],filter.region||'')}${select(t,h,'contentType','rehabContentType',[['',t('all')],...contentOptions(t)],filter.contentType||'')}<button class="secondary" type="submit">${h(t('programSearch'))}</button></form>`;
  const items=rows.map(r=>details(`content:${h(r.id)}`,`${h(r.title)} <span class="badge ${r.status==='published'?'green':'gold'}">${h(t('programStatus_'+r.status))}</span>`,`<div class="row wrap"><span class="badge">${h(t('rehabType_'+r.type))}</span><span class="badge">${h(t('rehabRegion_'+r.region))}</span><small>${h(r.language.toUpperCase())}</small></div>${r.description?`<p>${h(r.description)}</p>`:''}${r.content?`<p class="post-text">${h(r.content)}</p>`:empty(t,h,'rehabNoContent')}${content.canManage?`${details(`content-edit:${h(r.id)}`,h(t('wellnessEdit')),form(t,h,'rehabContentUpdate',contentFields(t,h,r),r.id),{edit:true})}${r.status==='draft'?details(`content-review:${h(r.id)}`,h(t('rehabReviewPublish')),`<p class="notice">${h(t('rehabReviewHint'))}</p>${form(t,h,'rehabContentPublish',field(t,h,'reviewer','rehabReviewer','','text','required maxlength="160"')+field(t,h,'source','rehabSource','','text','required maxlength="500"')+`<label class="check-row"><input type="checkbox" name="confirm" required>${h(t('rehabReviewConfirm'))}</label>`,r.id,'programPublish')}`,{edit:true}):''}${r.reviewedAt?`<small>${h(r.reviewer)} · ${h(r.source)}</small>`:''}<div class="row wrap">${r.status!=='draft'?action(t,h,btn,'rehabContentDraft',r.id,'programUnpublish'):''}${r.status!=='archived'?action(t,h,btn,'rehabContentArchive',r.id,'programArchive'):''}</div>`:''}`)).join('');
  return details('library',h(t('rehabContentLibrary')),`<p class="notice">${h(t('rehabContentNotice'))}</p>${content.canManage?details('content-add',h(t('rehabCreateDraft')),form(t,h,'rehabContentCreate',contentFields(t,h),undefined,'create'),{edit:true}):''}${filters}${items||empty(t,h,'rehabNoContent')}`,{open:true});
}
export function rehabPage({state,t,h,btn,filter={}}){
  const r=state.programs.rehab,content=state.programs.rehabContent;
  const header=`<div class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / REHAB PRO</span><h1>${h(t('rehab'))}</h1><p>${h(t('rehabIntro'))}</p></div><p class="notice">${h(t('programRehabNotice'))}</p>`;
  const library=libraryPage(content,{t,h,btn,filter});
  if(!r)return `<div class="stack rehab-pro">${header}${library||btn(t('health'),'nav','data-id="health"','secondary')}</div>`;
  const own=r.records,metrics=[['rehabOpenCases',own.filter(x=>x.status==='open').length],['rehabClosedCases',own.filter(x=>x.status==='closed').length],['rehabTimeline',own.reduce((n,x)=>n+x.checkins.length,0)]];
  const overview=`<section class="card stack"><h2>${h(t('rehabOverview'))}</h2><div class="dashboard-metrics">${metrics.map(([k,v])=>`<div class="stat-box"><div class="stat green">${v}</div><small>${h(t(k))}</small></div>`).join('')}</div></section>`;
  const cases=r.enabled?`${details('case-add',h(t('rehabNewCase')),form(t,h,'create',caseFields(t,h),undefined,'create'),{edit:true})}${own.map(x=>privateCase(x,{t,h,btn,choices:r.choices})).join('')||empty(t,h)}`:btn(t('health'),'nav','data-id="health"','secondary');
  const shared=r.shared.map(x=>privateCase(x,{t,h,btn,choices:[]},true)).join('')||empty(t,h);
  return `<div class="stack rehab-pro">${header}${overview}${details('personal',h(t('injuryLog')),cases,{open:true})}${details('shared',h(t('programShared')),shared)}${library}</div>`;
}
